public class Task10{static class Slot{private final int number;private String registration;Slot(int n){if(n<0)throw new IllegalArgumentException("Invalid slot");number=n;}public int getNumber(){return number;}public String getRegistration(){return registration;}public void park(String r){if(r==null||r.isBlank()||registration!=null)throw new IllegalArgumentException("Invalid or occupied");registration=r;}public void release(){registration=null;}}public static void main(String[]x){Slot s=new Slot(3);s.park("TN01AB1111");System.out.println("Slot: "+s.getNumber());System.out.println("Vehicle: "+s.getRegistration());try{s.park("TN02CD2222");}catch(IllegalArgumentException e){System.out.println("Duplicate occupancy rejected");}s.release();System.out.println("Free: "+(s.getRegistration()==null));}}